HasAllKantoMons.body:
u16 i;


    for (i = 0; i < KANTO_DEX_COUNT - 1; i++)
    {
        if (!GetSetPokedexFlag(i + 1, FLAG_GET_CAUGHT))
            return FALSE;
    }
    return TRUE;

HasAllMons.body:
u16 i;


    for (i = 0; i < KANTO_DEX_COUNT - 1; i++)
    {
        if (!GetSetPokedexFlag(i + 1, FLAG_GET_CAUGHT))
            return FALSE;
    }


    for (i = KANTO_DEX_COUNT; i < JOHTO_DEX_COUNT - 3; i++)
